mapper.select:
SELECT * FROM meeting_rooms
WHERE
    status = 'active'

        AND capacity_min <= #{attendeesCount} AND capacity_max >= #{attendeesCount}


        AND building = #{building}


        AND floor = #{floor}


        AND facilities @> '{"projector": ${facilities.projector}}'

            AND (facilities->>'whiteboard')::int >= #{facilities.whiteboard, jdbcType=INTEGER}


            AND (facilities->>'power_sockets')::int >= #{facilities.powerSockets, jdbcType=INTEGER}

        AND facilities @> '{"coffee_break": ${facilities.coffeeBreak}}'


                facilities @> '{"special_notes": #{note}}'
